        data: {
          action,
          repositoryId: repository.id,
          repositoryName: repository.full_name
        }
      });
    } catch (error) {
      this.jsonResponse(res, 500, {
        code: 'WEBHOOK_ERROR',
        message: error.message
      });
    }
  }

