    const allowed = rateLimiter.isAllowed(ip);
    assert(allowed === true, `${i}번째 요청 거부`);
  }

  // 11번째 요청은 거부
  const denied = rateLimiter.isAllowed(ip);
  assert(denied === false, '11번째 요청 허용됨');
});

test('IP별 독립적 제한', () => {
  rateLimiter.reset();
  const ip1 = '192.168.1.3';
