  // WebhookManager의 retryFailedEvents는 상태를 관리함
  const result = manager.retryFailedEvents();

  // 실패한 이벤트가 없는 경우
  if (!result.success) throw new Error('재시도 실패');
  if (result.retriedCount === undefined) throw new Error('재시도 카운트 누락');
});

