      return { success: true, webhooks: hooks };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  /**
   * 웹훅 제거
   */
  async deleteWebhook(owner, repo, hookId) {
    try {
      await this.request('DELETE', `/repos/${owner}/${repo}/hooks/${hookId}`);
      return { success: true };
    } catch (error) {
