    }
  }

  /**
   * 커밋 히스토리 조회
   */
  async getCommitHistory(owner, repo, limit = 20) {
    try {
      const commits = await this.request('GET', `/repos/${owner}/${repo}/commits?limit=${limit}`);
      return { success: true, commits };
