/**
 * 모니터링 시스템 - 실시간 통계 수집 및 분석
 *
 * 기능:
 * - 요청/응답 통계 (시간별, 분별)
 * - 에러율 및 성공률
 * - 응답 시간 분석 (평균, 최소, 최대, P95)
 * - Webhook 성공/실패 추적
 * - 메모리 및 CPU 모니터링
 * - 알림 시스템 (임계값 초과)
 */

class MonitoringSystem {
  constructor() {
    this.metrics = {
      // 요청 메트릭
      totalRequests: 0,
      totalErrors: 0,
      totalSuccesses: 0,

      // 시간별 데이터 (최근 60분)
      minuteData: {}, // { "HH:MM": { requests, errors, avgTime } }

      // 응답 시간
      responseTimes: [], // 최근 1000개 요청
      avgResponseTime: 0,
      maxResponseTime: 0,
      minResponseTime: 0,
      p95ResponseTime: 0,

      // 엔드포인트별 메트릭
      endpoints: {}, // { "/api/v1/search": { requests, errors, avgTime } }

      // Webhook 메트릭
      webhookMetrics: {
        totalWebhooks: 0,
        totalEvents: 0,
        successfulEvents: 0,
        failedEvents: 0,
        avgProcessingTime: 0
      },

      // 상태 코드별
      statusCodes: {}, // { "200": 100, "400": 5, "500": 2 }

      // 타임스탬프
      startTime: Date.now(),
      lastUpdated: Date.now()
    };

    // 알림 설정
    this.alerts = [];
    this.alertThresholds = {
      errorRateThreshold: 0.05, // 5%
      responseTimeThreshold: 1000, // 1초
      memoryUsageThreshold: 0.8, // 80%
      webhookFailureThreshold: 0.1 // 10%
    };

    // 매분마다 집계
    this.startAggregation();
  }

  /**
   * 요청 메트릭 기록
   */
  recordRequest(endpoint, statusCode, responseTime, isWebhook = false) {
    const now = new Date();
    const minuteKey = now.toISOString().slice(0, 16); // "2026-03-12T14:30"

    // 기본 통계
    this.metrics.totalRequests++;
    if (statusCode >= 400) {
      this.metrics.totalErrors++;
    } else {
      this.metrics.totalSuccesses++;
    }

    // 응답 시간 기록
    this.metrics.responseTimes.push(responseTime);
    if (this.metrics.responseTimes.length > 1000) {
      this.metrics.responseTimes.shift();
    }

    // 분별 데이터
    if (!this.metrics.minuteData[minuteKey]) {
      this.metrics.minuteData[minuteKey] = {
        requests: 0,
        errors: 0,
        totalTime: 0,
        maxTime: 0,
        minTime: Infinity
      };
    }
    this.metrics.minuteData[minuteKey].requests++;
    if (statusCode >= 400) {
      this.metrics.minuteData[minuteKey].errors++;
    }
    this.metrics.minuteData[minuteKey].totalTime += responseTime;
    this.metrics.minuteData[minuteKey].maxTime = Math.max(
      this.metrics.minuteData[minuteKey].maxTime,
      responseTime
    );
    this.metrics.minuteData[minuteKey].minTime = Math.min(
      this.metrics.minuteData[minuteKey].minTime,
      responseTime
    );

    // 엔드포인트별
    if (!this.metrics.endpoints[endpoint]) {
      this.metrics.endpoints[endpoint] = {
        requests: 0,
        errors: 0,
        totalTime: 0
      };
    }
    this.metrics.endpoints[endpoint].requests++;
    if (statusCode >= 400) {
      this.metrics.endpoints[endpoint].errors++;
    }
    this.metrics.endpoints[endpoint].totalTime += responseTime;

    // 상태 코드별
    if (!this.metrics.statusCodes[statusCode]) {
      this.metrics.statusCodes[statusCode] = 0;
    }
    this.metrics.statusCodes[statusCode]++;

    // 응답 시간 분석
    this.updateResponseTimeMetrics();

/**
 * PM2 Ecosystem Configuration
 * 프로덕션 배포 설정
 */

module.exports = {
  apps: [
    {
      name: 'gogs-architect-api',
      script: './src/api-server-v3.js',
      instances: 'max', // CPU 코어 수만큼 프로세스 실행
      exec_mode: 'cluster',
      env: {
        NODE_ENV: 'production',
        PORT: 3000,
        LOG_LEVEL: 'info'
      },
      env_staging: {
        NODE_ENV: 'staging',
        PORT: 3001,
        LOG_LEVEL: 'debug'
      },
      error_file: './logs/api-error.log',
      out_file: './logs/api-out.log',
      log_date_format: 'YYYY-MM-DD HH:mm:ss Z',
      merge_logs: true,

      // 자동 재시작
      watch: false, // 파일 변경 감시 (프로덕션에서는 false)
      ignore_watch: ['node_modules', 'logs', 'data'],
      max_restarts: 10,
      min_uptime: '10s',

      // 메모리 관리
      max_memory_restart: '512M',

      // Graceful shutdown
      kill_timeout: 5000, // 5초 후 강제 종료
      wait_ready: true,

      // 환경 변수
      instance_var: 'INSTANCE_ID'
    }
  ],

  deploy: {
    production: {
      user: 'deploy',
      host: ['253.49.254.93'], // 253 서버
      port: 22,
      key: '/home/deploy/.ssh/id_rsa',
      ref: 'origin/master',
      repo: 'https://github.com/anthropics/gogs-architect.git',
      path: '/opt/gogs-architect',
      'post-deploy': 'npm install && npm run build && pm2 restart ecosystem.config.js --env production',
      'pre-deploy-local': 'echo "Deploying to production..."',
      'ssh_options': [
        'StrictHostKeyChecking=no',
        'PasswordAuthentication=no'
      ]
    },
    staging: {
      user: 'deploy',
      host: ['staging.example.com'],
      port: 22,
      ref: 'origin/develop',
      repo: 'https://github.com/anthropics/gogs-architect.git',
      path: '/opt/gogs-architect-staging',
      'post-deploy': 'npm install && pm2 restart ecosystem.config.js --env staging'
    }
  },

  // 모니터링 설정
  monitoring: {
    enabled: true,
    memory_limit: 512,
    cpu_limit: 90
  }
};

