/**
 * FreeLang Light Parser
 * .free 파일을 파싱하여 AST (Abstract Syntax Tree) 생성
 */

class Token {
  constructor(type, value, line, col) {
    this.type = type;
    this.value = value;
    this.line = line;
    this.col = col;
  }
}

class Tokenizer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.col = 1;
    this.tokens = [];
  }

  isWhitespace(ch) {
    return /\s/.test(ch);
  }

  isIdentifierStart(ch) {
    return /[a-zA-Z_]/.test(ch);
  }

  isIdentifierChar(ch) {
    return /[a-zA-Z0-9_]/.test(ch);
  }

  isDigit(ch) {
    return /\d/.test(ch);
  }

  peek(offset = 0) {
    return this.source[this.pos + offset] || null;
  }

  advance() {
    const ch = this.source[this.pos];
    if (ch === '\n') {
      this.line++;
      this.col = 1;
    } else {
      this.col++;
    }
    this.pos++;
    return ch;
  }

  skipWhitespace() {
    while (this.isWhitespace(this.peek())) {
      this.advance();
    }
  }

  skipLineComment() {
    // //로 시작하는 댓글
    if (this.peek() === '/' && this.peek(1) === '/') {
      while (this.peek() !== '\n' && this.peek() !== null) {
        this.advance();
      }
      return true;
    }
    return false;
  }

  skipBlockComment() {
    // /* ... */로 시작하는 댓글
    if (this.peek() === '/' && this.peek(1) === '*') {
      this.advance(); // /
      this.advance(); // *
      while (!(this.peek() === '*' && this.peek(1) === '/') && this.peek() !== null) {
        this.advance();
      }
      if (this.peek() === '*') {
        this.advance(); // *
        this.advance(); // /
      }
      return true;
    }
    return false;
  }

  readString(quote) {
    let value = '';
    this.advance(); // 시작 따옴표
    while (this.peek() !== quote && this.peek() !== null) {
      if (this.peek() === '\\') {
        this.advance();
        const next = this.peek();
        if (next === 'n') value += '\n';
        else if (next === 't') value += '\t';
        else if (next === '"') value += '"';
        else if (next === "'") value += "'";

