/**
 * FreeLang v2 Phase 11: Dynamic Confidence Adjuster
 *
 * 목표: 패턴별 신뢰도를 사용자 피드백에 따라 동적으로 조정
 *
 * 알고리즘:
 * newConfidence = staticConfidence × usageFactor × successRate
 *
 * usageFactor = 1.0 + (usage / maxUsage) × 0.1
 * successRate = helpful / (helpful + unhelpful + 1)
 * clipped to: [0.70, 0.99]
 */

interface PatternFeedback {
  patternId: string;
  helpful: number;
  unhelpful: number;
  usageCount: number;
  lastUsed: Date;
  avgUserRating: number;  // 0-1
}

interface AdjustedPattern {
  patternId: string;
  originalConfidence: number;
  newConfidence: number;
  factors: {
    usageFactor: number;
    successRate: number;
    timeFactor: number;
  };
  updatedAt: Date;
}

class DynamicConfidenceAdjuster {
  /**
   * 패턴 신뢰도 조정
   */
  adjust(
    pattern: { id: string; confidence: number },
    feedback: PatternFeedback
  ): AdjustedPattern {
    // 1. 사용량 인수 계산 (더 자주 사용할수록 신뢰도 증가)
    const maxUsage = 1000; // 참조점
    const usageFactor = 1.0 + Math.min(feedback.usageCount / maxUsage, 1.0) * 0.1;

    // 2. 성공률 계산 (사용자 피드백)
    const totalFeedback = feedback.helpful + feedback.unhelpful + 1;
    const successRate = feedback.helpful / totalFeedback;

    // 3. 시간 인수 (신뢰도 유지, -0.1%/일)
    const daysSinceUsed = this.getDaysSince(feedback.lastUsed);
    const timeFactor = Math.max(1.0 - daysSinceUsed * 0.001, 0.9);

    // 4. 신뢰도 계산
    let newConfidence =
      pattern.confidence * usageFactor * successRate * timeFactor;

    // 5. 범위 제한 [0.70, 0.99]
    newConfidence = Math.max(0.70, Math.min(0.99, newConfidence));

    return {
      patternId: pattern.id,
      originalConfidence: pattern.confidence,
      newConfidence,
      factors: {
        usageFactor,
        successRate,
        timeFactor,
      },
      updatedAt: new Date(),
    };
  }

  /**
   * 여러 패턴의 신뢰도 일괄 조정
   */
  adjustBatch(
    patterns: Array<{ id: string; confidence: number }>,
    feedbackMap: Map<string, PatternFeedback>
  ): AdjustedPattern[] {
    return patterns.map(pattern => {
      const feedback = feedbackMap.get(pattern.id) || this.getDefaultFeedback();
      return this.adjust(pattern, feedback);
    });
  }

  /**
   * 신뢰도 변화 분석
   */
  analyzeChange(adjusted: AdjustedPattern): {
    increased: boolean;
    changePercent: number;
    reason: string;
  } {
    const change = adjusted.newConfidence - adjusted.originalConfidence;
    const changePercent = (change / adjusted.originalConfidence) * 100;

    let reason = '';
    if (adjusted.factors.successRate > 0.8) {
      reason = '높은 사용자 만족도';
    } else if (adjusted.factors.successRate < 0.4) {
      reason = '낮은 사용자 만족도';
    } else if (adjusted.factors.usageFactor > 1.05) {
      reason = '높은 사용 빈도';
    } else {
      reason = '시간 경과에 따른 감소';
    }

    return {
      increased: change > 0,
      changePercent: Math.round(changePercent * 100) / 100,
      reason,
    };
  }

  /**
   * 신뢰도 통계
   */
  calculateStats(adjustedPatterns: AdjustedPattern[]): {
    averageConfidence: number;
    highConfidenceCount: number;  // >= 0.85
    lowConfidenceCount: number;   // < 0.70
    totalImprovement: number;
  } {
    const stats = {
      averageConfidence: 0,
      highConfidenceCount: 0,
      lowConfidenceCount: 0,
      totalImprovement: 0,
    };

    let sum = 0;
    for (const pattern of adjustedPatterns) {
      sum += pattern.newConfidence;

      if (pattern.newConfidence >= 0.85) {
        stats.highConfidenceCount++;
      } else if (pattern.newConfidence < 0.70) {
        stats.lowConfidenceCount++;
      }

      stats.totalImprovement +=
        pattern.newConfidence - pattern.originalConfidence;
    }

    stats.averageConfidence = sum / adjustedPatterns.length;

    return stats;
  }

  /**
   * 기본 피드백 생성 (데이터 부재 시)
   */
  private getDefaultFeedback(): PatternFeedback {
    return {
      patternId: '',
      helpful: 0,
      unhelpful: 0,
      usageCount: 0,
      lastUsed: new Date(),
      avgUserRating: 0.5,
    };
  }

  /**
   * 날짜 차이 계산
   */
  private getDaysSince(date: Date): number {
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    return diff / (1000 * 60 * 60 * 24);
  }
}

export { DynamicConfidenceAdjuster, PatternFeedback, AdjustedPattern };

