     1→/**
     2→ * Phase 11: Feedback Analyzer
     3→ *
     4→ * Maps feedback entries (from Phase 8) to Intent patterns (from Phase 10)
     5→ * and generates usage metrics for confidence adjustment.
     6→ */
     7→
     8→import { FeedbackEntry, FeedbackStats } from '../feedback/feedback-types';
     9→import { IntentPattern } from '../phase-10/unified-pattern-database';
    10→
    11→/**
    12→ * Usage metrics for a single pattern
    13→ */
    14→export interface PatternUsageMetrics {
    15→  patternId: string;
    16→  patternName: string;
    17→  usageCount: number;
    18→  approvedCount: number;
    19→  modifiedCount: number;
    20→  rejectedCount: number;
    21→  suggestedCount: number;
    22→
    23→  // Calculated metrics
    24→  approvalRate: number;       // approved / total
    25→  modificationRate: number;   // modified / total
    26→  rejectionRate: number;      // rejected / total
    27→  averageAccuracy: number;    // 0.0-1.0
    28→
    29→  // Statistics
    30→  firstUsed?: number;         // timestamp
    31→  lastUsed?: number;          // timestamp
    32→  sessionCount: number;       // unique sessions
    33→  avgAccuracyPerSession: number;
    34→}
    35→
    36→/**
    37→ * Aggregated statistics for all patterns
    38→ */
    39→export interface AggregatedStats {
    40→  totalFeedbackEntries: number;
    41→  totalPatterns: number;
    42→  patternsWithFeedback: number;
    43→  patternsWithoutFeedback: number;
    44→
    45→  approvalRate: number;
    46→  modificationRate: number;
    47→  rejectionRate: number;
    48→
    49→  metrics: Map<string, PatternUsageMetrics>;
    50→  categoryStats: Map<string, CategoryStats>;
    51→}
    52→
    53→/**
    54→ * Per-category statistics
    55→ */
    56→export interface CategoryStats {
    57→  category: string;
    58→  patternCount: number;
    59→  feedbackCount: number;
    60→  approvalRate: number;
    61→  averageAccuracy: number;
    62→}
    63→
    64→/**
    65→ * Feedback Analyzer
    66→ *
    67→ * Maps feedback entries to patterns and calculates usage metrics
    68→ */
    69→export class FeedbackAnalyzer {
    70→  private patterns: Map<string, IntentPattern>;
    71→  private uniquePatterns: Map<string, IntentPattern>; // Track unique patterns by ID
    72→  private feedbackByPattern: Map<string, FeedbackEntry[]>;
    73→
    74→  constructor(allPatterns: IntentPattern[]) {
    75→    // Index patterns by name and aliases for quick lookup
    76→    this.patterns = new Map();
    77→    this.uniquePatterns = new Map();
    78→
    79→    for (const pattern of allPatterns) {
    80→      this.patterns.set(pattern.name, pattern);
    81→      this.uniquePatterns.set(pattern.id, pattern);
    82→
    83→      // Also index by aliases for flexible matching
    84→      for (const alias of pattern.aliases) {
    85→        this.patterns.set(alias.toLowerCase(), pattern);
    86→      }
    87→    }
    88→
    89→    this.feedbackByPattern = new Map();
    90→  }
    91→
    92→  /**
    93→   * Analyze feedback and map to patterns
    94→   */
    95→  analyzeFeedback(feedbackEntries: FeedbackEntry[]): AggregatedStats {
    96→    // Reset state
    97→    this.feedbackByPattern.clear();
    98→
    99→    // Group feedback by pattern
   100→    for (const entry of feedbackEntries) {
   101→      const patternName = this.mapOperationToPattern(entry.proposal.operation);
   102→
   103→      if (patternName) {
   104→        if (!this.feedbackByPattern.has(patternName)) {
   105→          this.feedbackByPattern.set(patternName, []);
   106→        }
   107→        this.feedbackByPattern.get(patternName)!.push(entry);
   108→      }
   109→    }
   110→
   111→    // Calculate metrics for each pattern
   112→    const metrics = new Map<string, PatternUsageMetrics>();
   113→
   114→    for (const [patternName, feedback] of this.feedbackByPattern) {
   115→      const pattern = this.patterns.get(patternName);
   116→      if (pattern) {
   117→        metrics.set(pattern.id, this.calculateMetrics(pattern, feedback));
   118→      }
   119→    }
   120→
   121→    // Calculate category stats
   122→    const categoryStats = this.calculateCategoryStats(metrics);
   123→
   124→    // Return aggregated statistics
   125→    return {
   126→      totalFeedbackEntries: feedbackEntries.length,
   127→      totalPatterns: this.uniquePatterns.size,
   128→      patternsWithFeedback: metrics.size,
   129→      patternsWithoutFeedback: this.uniquePatterns.size - metrics.size,
   130→      approvalRate: this.calculateOverallApprovalRate(metrics),
   131→      modificationRate: this.calculateOverallModificationRate(metrics),
   132→      rejectionRate: this.calculateOverallRejectionRate(metrics),
   133→      metrics,
   134→      categoryStats,
   135→    };
   136→  }
   137→
   138→  /**
   139→   * Map operation name to pattern name
   140→   * Examples: "sum" → "sum", "add_all" → "sum", "total" → "sum"
   141→   */
   142→  private mapOperationToPattern(operation: string): string | null {
   143→    const normalized = operation.toLowerCase();
   144→
   145→    // Direct match
   146→    if (this.patterns.has(normalized)) {
   147→      return normalized;
   148→    }
   149→
   150→    // Check aliases
   151→    for (const [alias, pattern] of this.patterns) {
   152→      if (alias.includes(normalized) || normalized.includes(alias)) {
   153→        return pattern.name;
   154→      }
   155→    }
   156→
   157→    return null;
   158→  }
   159→
   160→  /**
   161→   * Calculate usage metrics for a pattern based on its feedback
   162→   */
   163→  private calculateMetrics(
   164→    pattern: IntentPattern,
   165→    feedback: FeedbackEntry[]
   166→  ): PatternUsageMetrics {
   167→    const approved = feedback.filter(f => f.userFeedback.action === 'approve').length;
   168→    const modified = feedback.filter(f => f.userFeedback.action === 'modify').length;
   169→    const rejected = feedback.filter(f => f.userFeedback.action === 'reject').length;
   170→    const suggested = feedback.filter(f => f.userFeedback.action === 'suggest').length;
   171→
   172→    const total = feedback.length;
   173→    const accuracies = feedback.map(f => f.analysis.accuracy);
   174→    const averageAccuracy = total > 0
   175→      ? accuracies.reduce((a, b) => a + b, 0) / total
   176→      : 0;
   177→
   178→    // Calculate per-session metrics
   179→    const sessions = new Set(feedback.map(f => f.sessionId));
   180→    const sessionAccuracies: Map<string, number[]> = new Map();
   181→
   182→    for (const entry of feedback) {
   183→      if (!sessionAccuracies.has(entry.sessionId)) {
   184→        sessionAccuracies.set(entry.sessionId, []);
   185→      }
   186→      sessionAccuracies.get(entry.sessionId)!.push(entry.analysis.accuracy);
   187→    }
   188→
   189→    const avgAccuracyPerSession = Array.from(sessionAccuracies.values())
   190→      .map(accs => accs.reduce((a, b) => a + b, 0) / accs.length)
   191→      .reduce((a, b) => a + b, 0) / sessions.size;
   192→
   193→    // Get timestamps
   194→    const timestamps = feedback.map(f => f.timestamp).sort((a, b) => a - b);
   195→
   196→    return {
   197→      patternId: pattern.id,
   198→      patternName: pattern.name,
   199→      usageCount: total,
   200→      approvedCount: approved,
   201→      modifiedCount: modified,
   202→      rejectedCount: rejected,
   203→      suggestedCount: suggested,
   204→
   205→      approvalRate: total > 0 ? approved / total : 0,
   206→      modificationRate: total > 0 ? modified / total : 0,
   207→      rejectionRate: total > 0 ? rejected / total : 0,
   208→      averageAccuracy,
   209→
   210→      firstUsed: timestamps.length > 0 ? timestamps[0] : undefined,
   211→      lastUsed: timestamps.length > 0 ? timestamps[timestamps.length - 1] : undefined,
   212→      sessionCount: sessions.size,
   213→      avgAccuracyPerSession,
   214→    };
   215→  }
   216→
   217→  /**
   218→   * Calculate statistics by category
   219→   */
   220→  private calculateCategoryStats(
   221→    metrics: Map<string, PatternUsageMetrics>
   222→  ): Map<string, CategoryStats> {
   223→    const stats = new Map<string, CategoryStats>();
   224→
   225→    for (const [patternId, metric] of metrics) {
   226→      const pattern = Array.from(this.patterns.values()).find(p => p.id === patternId);
   227→      if (!pattern) continue;
   228→
   229→      const category = pattern.category;
   230→      if (!stats.has(category)) {
   231→        // Count total patterns in category
   232→        const patternsInCategory = Array.from(this.patterns.values())
   233→          .filter(p => p.category === category).length;
   234→
   235→        stats.set(category, {
   236→          category,
   237→          patternCount: patternsInCategory,
   238→          feedbackCount: 0,
   239→          approvalRate: 0,
   240→          averageAccuracy: 0,
   241→        });
   242→      }
   243→
   244→      const cat = stats.get(category)!;
   245→      cat.feedbackCount += metric.usageCount;
   246→    }
   247→
   248→    // Calculate averages
   249→    for (const [category, stat] of stats) {
   250→      const patternsInCategory = Array.from(metrics.values())
   251→        .filter(m => {
   252→          const p = Array.from(this.patterns.values()).find(x => x.id === m.patternId);
   253→          return p && p.category === category;
   254→        });
   255→
