      if (data.title !== 'API Post') throw new Error('Title mismatch');
    }
  };

  api.handle(req, res);
});

test('API read post', () => {
  const db = new BlogDatabase('/tmp/test-api-2.json');
  const created = db.create({ title: 'Read Test', author: 'Jane', content: 'X', category: 'News', tags: '', slug: 'read' });

  const api = new BlogAPI(db);
  const req = { url: `/api/blogs/${created.id}`, method: 'GET' };

  let statusCode;
  let responseBody = '';
  const res = {
    setHeader: () => {},
