```bash
# Create blog post
curl -X POST http://localhost:3000/api/blogs \
  -H "Content-Type: application/json" \
  -d '{
    "title": "Getting Started with FreeLang",
    "description": "Learn FreeLang basics",
    "content": "FreeLang is a self-hosting...",
    "author": "Jane Doe",
    "category": "Tutorial",
