    this.dataPath = dataPath;
    this.posts = new Map();
    this.nextId = 1;
    this.load();
    this.validateAndRepair();
  }

  load() {
    try {
      if (fs.existsSync(this.dataPath)) {
        const data = JSON.parse(fs.readFileSync(this.dataPath, 'utf-8'));
        if (data.posts && Array.isArray(data.posts)) {
