// ============================================================================
// PART 5: Graceful Shutdown
// ============================================================================

process.on('SIGINT', () => {
  console.log('\n\n📦 Saving database...');
  db.save();
  server.close(() => {
    console.log('✅ Server stopped\n');
    process.exit(0);
  });
});

module.exports = { BlogDatabase, BlogAPI, BlogComponentParser };

