  console.log('  POST   /api/blogs/:id/like     - Increment likes');
  console.log('\n📊 Analytics Endpoints:');
  console.log('  GET    /api/stats              - Blog statistics & top posts');
  console.log('  GET    /api/search?q=...       - Full-text search across all posts');
